//! COBOL (GnuCOBOL >= 3): the `azul.cpy` copybook (generated by
//! `doc/src/codegen/v2/lang_cobol`), `COPY "azul.cpy".` in WORKING-STORAGE.
//!
//! The copybook declares one `TYAZ-<TYPE>` TYPEDEF record per type, one
//! level-78 constant per C-like enum variant (`AZ-LAYOUT-DISPLAY-FLEX`,
//! reserved words get `-X`: `AZ-CSS-PROPERTY-TYPE-WIDTH-X`) and upper-case
//! hyphenated field names (`NUMBER-X`, `INNER`); every name longer than 30
//! characters is cut to 25 plus `-` and 4 hex digits of its FNV-1a hash
//! (`TYAZ-CSS-PROPERTY-WITH-CO-8550`). Those rules are ported here verbatim.
//!
//! COBOL cannot nest calls nor receive a struct as a CALL result, so every
//! value is a data item ([`super::linear`]) filled by the out-parameter
//! twin of the C function: `CALL "AzCssProperty_widthByref" USING BY
//! REFERENCE t2 BY REFERENCE t1` (structs by reference, enums / integers BY
//! VALUE, a float BY VALUE from a `FLOAT-SHORT` item). The copybook's
//! `FN-*` name constants have no `...Byref` entries, so the C symbol is
//! called as a literal. A style is a subprogram (`PROGRAM-ID. STYLE-BTN.`)
//! returning its Vec through its LINKAGE record.
//!
//! Limitations: the copybook gives a `CssPropertyValue<T>` alias / a
//! `CssProperty` only a raw `TAG` + `PAYLOAD-ANCHOR PIC X(64)` record, so
//! those unions are not built by hand. Caveat for the bindings: the TYPEDEF
//! records are packed (no `SYNC`), so a record with C padding (e.g.
//! `PixelValue`) is smaller than the C struct the `...Byref` call writes.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use super::linear::{item_blocker, linear_comments, lower_to_statements, LinearSyntax};
use crate::codegen::{
    ir::{snake_to_lower_camel, EnumShape, Expr, Item, Module, Prim},
    lang::variant_ctor_method,
    CodegenBackend, GeneratedFile,
};

/// The COBOL printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Cobol;

/// `to_cobol_case` of `lang_cobol/mod.rs`.
fn cobol_case(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let mut out = String::new();
    for (i, &c) in chars.iter().enumerate() {
        if c == '_' {
            if !out.ends_with('-') {
                out.push('-');
            }
        } else if c.is_uppercase() && i > 0 {
            let prev = chars[i - 1];
            let next = chars.get(i + 1).copied();
            let boundary = prev.is_lowercase()
                || prev.is_ascii_digit()
                || (prev.is_uppercase() && next.is_some_and(char::is_lowercase));
            if boundary && !out.ends_with('-') {
                out.push('-');
            }
            out.push(c.to_ascii_uppercase());
        } else {
            out.push(c.to_ascii_uppercase());
        }
    }
    while out.contains("--") {
        out = out.replace("--", "-");
    }
    out.trim_matches('-').to_string()
}

/// `fnv1a_hex` of `lang_cobol/mod.rs`.
fn fnv1a_hex(s: &str) -> String {
    let mut h: u32 = 0x811c_9dc5;
    for b in s.bytes() {
        h ^= u32::from(b);
        h = h.wrapping_mul(0x0100_0193);
    }
    format!("{:04x}", h & 0xffff)
}

/// `mangle_identifier` of `lang_cobol/mod.rs` (30-character limit).
fn mangle(name: &str) -> String {
    if name.len() <= 30 {
        return name.to_string();
    }
    let mut out: String = name.chars().take(25).collect();
    while out.ends_with('-') {
        out.pop();
    }
    out.push('-');
    out.push_str(&fnv1a_hex(name));
    out
}

/// `cobol_identifier` of `lang_cobol/mod.rs`.
fn identifier(name: &str) -> String {
    mangle(&cobol_case(name))
}

/// `sanitize_cobol_identifier` of `lang_cobol/mod.rs`.
fn sanitize(name: &str) -> String {
    let upper = name.to_ascii_uppercase();
    let upper = if upper.starts_with(|c: char| c.is_ascii_digit()) {
        format!("FIELD-{upper}")
    } else {
        upper
    };
    if RESERVED.contains(&upper.as_str()) {
        format!("{upper}-X")
    } else {
        upper
    }
}

/// `TYAZ-<TYPE>` record TYPEDEF.
fn typedef(ty: &str) -> String {
    identifier(&format!("TYAZ-{}", cobol_case(ty)))
}

/// The level-78 constant of a C-like enum variant.
fn constant(ty: &str, variant: &str) -> String {
    let class = identifier(&format!("AZ-{}", cobol_case(ty)));
    identifier(&format!("{class}-{}", sanitize(&cobol_case(variant))))
}

/// A record field name.
fn field(name: &str) -> String {
    sanitize(&cobol_case(name))
}

/// A literal: printable ASCII in quotes (quote doubled), else hex.
fn cobol_literal(s: &str) -> String {
    if s.bytes().all(|b| (0x20..0x7f).contains(&b)) {
        let mut out = String::from("\"");
        for c in s.chars() {
            if c == '"' {
                out.push('"');
            }
            out.push(c);
        }
        out.push('"');
        out
    } else {
        let hex: String = s.bytes().map(|b| format!("{b:02X}")).collect();
        format!("X\"{hex}\"")
    }
}

/// A temporary (`t1`), passed BY REFERENCE; anything else (a literal, a
/// level-78 constant) BY VALUE; operands that already say how stay as they
/// are (`BY VALUE t3` for a scalar item).
fn operand(arg: &str) -> String {
    let is_temp = arg.strip_prefix('t').is_some_and(|n| {
        !n.is_empty() && n.bytes().all(|b| b.is_ascii_digit())
    });
    if arg.starts_with("BY ") {
        arg.to_string()
    } else if is_temp {
        format!("BY REFERENCE {arg}")
    } else {
        format!("BY VALUE {arg}")
    }
}

/// `CALL "<symbol>Byref" USING BY REFERENCE <target> <args>`.
fn call_byref(symbol: &str, target: &str, args: &[String]) -> String {
    let mut out = format!("CALL \"{symbol}Byref\" USING BY REFERENCE {target}");
    for a in args {
        out.push(' ');
        out.push_str(&operand(a));
    }
    out.push_str(" END-CALL");
    out
}

/// Marker prefix of an `isize` / `usize` literal: those fields are
/// `USAGE POINTER` in the copybook, set with `SET .. UP BY`.
const POINTER_LITERAL: &str = "POINTER:";

impl LinearSyntax for Cobol {
    fn dom_limitation(&self) -> Option<&'static str> {
        Some(
            "the copybook's records are packed (no SYNC or FILLER), so an AzDom record is \
             smaller than the C struct `AzDom_withChildByref` writes into it (its AzDomVec ends \
             in a 1-byte FLAGS-X without the C padding), and COBOL cannot define the C function \
             an app's layout callback must be",
        )
    }

    fn int(&self, value: i128, ty: Prim) -> String {
        if matches!(ty, Prim::Isize | Prim::Usize) {
            format!("{POINTER_LITERAL}{value}")
        } else {
            value.to_string()
        }
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        text.to_string()
    }

    fn boolean(&self, b: bool) -> String {
        String::from(if b { "1" } else { "0" })
    }

    fn clike(&self, ty: &str, variant: &str) -> String {
        constant(ty, variant)
    }

    fn type_name(&self, ty: &str) -> String {
        format!("USAGE {}", typedef(ty))
    }

    fn array_type(&self, elem: &str, n: usize) -> String {
        format!("OCCURS {n} {}", typedef(elem))
    }

    fn call(&self, target: &str, class: &str, method: &str, args: &[String]) -> Vec<String> {
        let symbol = format!("Az{class}_{}", snake_to_lower_camel(method));
        vec![call_byref(&symbol, target, args)]
    }

    fn variant_call(&self, target: &str, ty: &str, variant: &str, args: &[String]) -> Vec<String> {
        let symbol = format!("Az{ty}_{}", variant_ctor_method(variant));
        vec![call_byref(&symbol, target, args)]
    }

    fn union(
        &self,
        target: &str,
        _ty: &str,
        _variant: &str,
        tag: usize,
        _payload: Option<&str>,
    ) -> Vec<String> {
        // unreachable: `limitation` rejects every hand-built union
        vec![format!("MOVE {tag} TO TAG OF {target}")]
    }

    fn set_field(&self, target: &str, _ty: &str, name: &str, value: &str) -> String {
        let f = field(name);
        match value.strip_prefix(POINTER_LITERAL) {
            Some(n) => match n.strip_prefix('-') {
                Some(neg) => format!(
                    "SET {f} OF {target} TO NULL SET {f} OF {target} DOWN BY {neg}"
                ),
                None => format!("SET {f} OF {target} TO NULL SET {f} OF {target} UP BY {n}"),
            },
            None => format!("MOVE {value} TO {f} OF {target}"),
        }
    }

    fn set_elem(&self, arr: &str, index: usize, value: &str) -> String {
        format!("MOVE {value} TO {arr}-item ({})", index + 1)
    }

    fn vec_from_array(&self, target: &str, ty: &str, _elem: &str, arr: &str, count: &str) -> Vec<String> {
        vec![format!(
            "CALL \"Az{ty}_copyFromPtrByref\" USING BY REFERENCE {target} BY REFERENCE {arr} \
             {} END-CALL",
            operand(count)
        )]
    }

    fn vec_empty(&self, target: &str, ty: &str) -> Vec<String> {
        vec![format!("CALL \"Az{ty}_createByref\" USING BY REFERENCE {target} END-CALL")]
    }

    fn string(&self, target: &str, _s: &str) -> Vec<String> {
        // unreachable: `string_buffer` always declares the bytes
        vec![format!("CALL \"AzString_createByref\" USING BY REFERENCE {target} END-CALL")]
    }

    fn string_buffer(&self, s: &str) -> Option<String> {
        Some(format!("BYTES {} {}", s.len(), cobol_literal(s)))
    }

    fn string_from_buffer(&self, target: &str, buf: &str, _s: &str) -> Vec<String> {
        vec![format!(
            "CALL \"AzString_copyFromBytesByref\" USING BY REFERENCE {target} BY REFERENCE \
             {buf}-bytes BY VALUE {buf}-start BY VALUE {buf}-len END-CALL"
        )]
    }

    fn scalar_arg(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Float { text, ty } => Some(format!(
                "USAGE {} VALUE {text}",
                if *ty == Prim::F64 {
                    "FLOAT-LONG"
                } else {
                    "FLOAT-SHORT"
                }
            )),
            Expr::Int { value, ty } => match ty {
                Prim::Usize | Prim::U64 => {
                    Some(format!("USAGE BINARY-DOUBLE UNSIGNED VALUE {value}"))
                }
                Prim::Isize | Prim::I64 => Some(format!("USAGE BINARY-DOUBLE VALUE {value}")),
                _ => None,
            },
            _ => None,
        }
    }

    fn scalar_operand(&self, temp: &str) -> String {
        format!("BY VALUE {temp}")
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Variant {
                ty,
                shape: EnumShape::Generic { .. } | EnumShape::TaggedShadowed,
                ..
            } => Some(format!(
                "the COBOL copybook gives `{ty}` only a raw TAG + PAYLOAD-ANCHOR record \
                 (no constructor, no payload layout)"
            )),
            Expr::Float { text, .. } if text == "nan" || text.ends_with("inf") => {
                Some("COBOL has no literal for NaN / infinity".to_string())
            }
            _ => None,
        }
    }
}

/// A style's PROGRAM-ID: `style_btn` -> `STYLE-BTN`.
fn program_id(item: &Item) -> String {
    mangle(&sanitize(&cobol_case(&item.name.snake())))
}

/// The WORKING-STORAGE entry of one temporary.
fn declaration(name: &str, decl: &str) -> String {
    if let Some(rest) = decl.strip_prefix("OCCURS ") {
        let (n, td) = rest.split_once(' ').unwrap_or((rest, ""));
        return format!("01  {name}.\n    05  {name}-item USAGE {td} OCCURS {n} TIMES.\n");
    }
    if let Some(rest) = decl.strip_prefix("BYTES ") {
        let (n, lit) = rest.split_once(' ').unwrap_or((rest, "\"\""));
        let (pic, value) = if n == "0" {
            ("1", "SPACE")
        } else {
            (n, lit)
        };
        return format!(
            "01  {name}.\n    05  {name}-start USAGE BINARY-DOUBLE UNSIGNED VALUE 0.\n    05  \
             {name}-len USAGE BINARY-DOUBLE UNSIGNED VALUE {n}.\n    05  {name}-bytes PIC \
             X({pic}) VALUE {value}.\n"
        );
    }
    format!("01  {name} {decl}.\n")
}

fn comment(text: &str) -> String {
    format!("*> {}\n", text.replace(['\n', '\r'], " "))
}

/// One subprogram per style (`None` if the bindings cannot build it).
fn item_program(item: &Item) -> (bool, String) {
    let id = program_id(item);
    if let Some(reason) = item_blocker(&Cobol, item) {
        return (
            false,
            comment(&format!("{id}: not expressible with the COBOL bindings: {reason}")),
        );
    }
    let st = lower_to_statements(&Cobol, &item.value);
    let mut out = String::new();
    for line in linear_comments(item, &st) {
        out.push_str(&comment(&line));
    }
    out.push_str(&format!(
        "IDENTIFICATION DIVISION.\nPROGRAM-ID. {id}.\nDATA DIVISION.\nWORKING-STORAGE \
         SECTION.\nCOPY \"azul.cpy\".\n"
    ));
    for (n, t) in &st.decls {
        out.push_str(&declaration(n, t));
    }
    out.push_str(&format!(
        "LINKAGE SECTION.\n01  ls-result USAGE {}.\nPROCEDURE DIVISION USING ls-result.\n",
        typedef(&item.ty)
    ));
    for s in &st.body {
        out.push_str(&format!("    {s}\n"));
    }
    out.push_str(&format!(
        "    MOVE {} TO ls-result\n    GOBACK.\nEND PROGRAM {id}.\n",
        st.result
    ));
    (true, out)
}

impl CodegenBackend for Cobol {
    fn lang(&self) -> &'static str {
        "cobol"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["gnucobol", "cob"]
    }

    fn display_name(&self) -> &'static str {
        "COBOL"
    }

    fn extension(&self) -> &'static str {
        "cob"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            ">>SOURCE FORMAT IS FREE\n*> Generated by azul-css codegen (COBOL). Do not edit by \
             hand.\n*> One subprogram per style: CALL \"<PROGRAM-ID>\" USING BY REFERENCE \
             <result record>.\n",
        );
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_program(item).1);
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let built: Vec<&Item> = m.items.iter().filter(|i| item_program(i).0).collect();
        let mut main = String::from(
            ">>SOURCE FORMAT IS FREE\n*> Copy target/codegen/azul.cpy and libazul here, \
             then:\n*>   cobc -x -free main.cob styles.cob -L. -lazul -o main && \
             ./main\nIDENTIFICATION DIVISION.\nPROGRAM-ID. MAIN-STYLES.\nDATA \
             DIVISION.\nWORKING-STORAGE SECTION.\nCOPY \"azul.cpy\".\n",
        );
        for (i, item) in built.iter().enumerate() {
            main.push_str(&format!("01  ws-value-{} USAGE {}.\n", i + 1, typedef(&item.ty)));
        }
        main.push_str("PROCEDURE DIVISION.\n");
        for (i, item) in built.iter().enumerate() {
            let id = program_id(item);
            main.push_str(&format!(
                "    CALL \"{id}\" USING BY REFERENCE ws-value-{} END-CALL\n    DISPLAY \"{id}: \
                 built\"\n",
                i + 1
            ));
        }
        main.push_str("    STOP RUN.\nEND PROGRAM MAIN-STYLES.\n");
        vec![
            GeneratedFile {
                path: "styles.cob".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.cob".to_string(),
                contents: main,
            },
        ]
    }
}

